package cn.aiworkspace.personal;
// Native UI/database tests use only SYNTHETIC text and a test-only crypto boundary.
import android.app.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import org.robolectric.shadows.ShadowLooper;
import java.io.*;
import java.util.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=WorkspaceApp.class,shadows={NativeChecks.TestVault.class},qualifiers="w393dp-h852dp-mdpi")
@GraphicsMode(GraphicsMode.Mode.NATIVE)
public class NativeChecks {
 @Implements(value=KeyVault.class,isInAndroidSdk=false)
 public static class TestVault {
  @Implementation protected static String seal(String s){return "SYNTHETIC_CIPHER_"+s;}
  @Implementation protected static String open(String s){return s.replace("SYNTHETIC_CIPHER_","");}
 }
 WorkspaceApp app;MainActivity activity;
 @Before public void setup(){app=(WorkspaceApp)RuntimeEnvironment.getApplication();activity=Robolectric.buildActivity(MainActivity.class).setup().get();if(activity.getActionBar()!=null)activity.getActionBar().hide();}
 void saveProvider()throws Exception{JSONObject p=activity.preset(0);p.put("keyCipher","SYNTHETIC_CIPHER_SYNTHETIC_KEY");app.store.saveProvider(p);JSONObject chat=app.store.chat(activity.chatId);chat.put("providerId",p.getString("id"));chat.put("model","SYNTHETIC_MODEL");app.store.saveChat(chat);}
 @Test public void launchAndNavigationKeepDraftWithoutModelCall()throws Exception{assertEquals("chat",activity.page);assertEquals(0,app.store.providers().length());assertNull(app.store.active());activity.composer.setText("合成输入，切页后保留");activity.providersPage();assertEquals("providers",activity.page);activity.chatPage();assertEquals("合成输入，切页后保留",activity.composer.getText().toString());assertEquals(0,app.store.backup().getJSONObject("data").getJSONArray("requests").length());}
 @Test public void createProjectThenChatHasIndependentConversation()throws Exception{String initial=activity.chatId;app.store.saveProject(J.obj("id","SYNTHETIC_PROJECT","name","合成项目","instructions","合成专属说明"));activity.projectId="SYNTHETIC_PROJECT";activity.newChat();assertNotEquals(initial,activity.chatId);assertEquals("SYNTHETIC_PROJECT",app.store.chat(activity.chatId).getString("projectId"));activity.composer.setText("另一份合成草稿");activity.openChat(initial);assertEquals("",activity.composer.getText().toString());assertEquals("另一份合成草稿",app.store.chats("SYNTHETIC_PROJECT").getJSONObject(0).getString("draft"));}
 @Test public void providerFormSaveAndNavigationPreserveTypedKey()throws Exception{activity.providerPage("",0);activity.form.key.setText("SYNTHETIC_KEY");String id=activity.form.id;activity.form.max.setText("8192");activity.providersPage();activity.providerPage(id,0);assertEquals("SYNTHETIC_KEY",activity.form.key.getText().toString());assertEquals("8192",activity.form.max.getText().toString());JSONObject p=activity.gatherForm(activity.form,true);assertEquals(8192,p.optInt("maxTokens"));assertNull(app.store.active());}
 @Test public void reserveIsAtomicPreventsDuplicateAndSnapshotsModel()throws Exception{saveProvider();Store s=app.store;JSONObject r=s.reserve(activity.chatId,"合成问题一");assertEquals(2,s.messages(activity.chatId).length());assertEquals("queued",r.getString("status"));try{s.reserve(activity.chatId,"合成问题二");fail("duplicate reservation");}catch(IllegalArgumentException expected){}assertEquals(2,s.messages(activity.chatId).length());JSONObject c=s.chat(activity.chatId);c.put("model","SYNTHETIC_NEW_MODEL");s.saveChat(c);assertEquals("SYNTHETIC_MODEL",s.request(r.getString("id")).getJSONObject("data").getString("model"));assertTrue(s.begin(r.getString("id")));assertFalse(s.begin(r.getString("id")));s.stop(r.getString("id"));assertNull(s.active());}
 @Test public void sqliteReopenPreservesDraftAndDoesNotReplayInterruptedRequest()throws Exception{saveProvider();String id=activity.chatId;JSONObject r=app.store.reserve(id,"合成中断问题");app.store.begin(r.getString("id"));ApiProtocol.Output o=new ApiProtocol.Output();o.text.append("合成部分回答");app.store.partial(r.getString("id"),o);app.store.draft(id,"合成未发草稿");app.store.close();Store reopened=new Store(app);assertEquals("interrupted",reopened.request(r.getString("id")).getString("status"));assertEquals("合成部分回答",reopened.lastMessage(id).getString("body"));assertEquals("合成未发草稿",reopened.chat(id).getString("draft"));assertNull(reopened.active());reopened.close();}
 @Test public void projectFileContextAndBackupExcludeKeysRestoreNoAutoRun()throws Exception{saveProvider();app.store.addFile("inbox","合成参考.md","仅供自动测试的合成参考资料");JSONObject r=app.store.reserve(activity.chatId,"合成项目上下文问题");assertTrue(r.getJSONObject("data").getJSONObject("payload").toString().contains("合成参考资料"));JSONObject b=app.store.backup();assertFalse(b.toString().contains("SYNTHETIC_CIPHER"));assertFalse(b.toString().contains("SYNTHETIC_KEY"));app.store.stop(r.getString("id"));int count=app.store.restore(b);assertEquals(0,count);assertNull(app.store.active());}
 @Test public void lateReplyDoesNotReplaceProjectFormOrComposer()throws Exception{saveProvider();String id=activity.chatId;JSONObject r=app.store.reserve(id,"合成问题");app.store.begin(r.getString("id"));activity.projectPage("inbox");View current=activity.root;ApiProtocol.Output o=new ApiProtocol.Output();o.text.append("合成回答");app.store.partial(r.getString("id"),o);activity.changed(id,false);assertSame(current,activity.root);assertEquals("project",activity.page);app.store.finish(r.getString("id"),"done",o,"");activity.changed(id,true);assertSame(current,activity.root);}
 @Test public void actualConnectAndSaveButtonsPersistApiProfile()throws Exception{tap("接入第一个 AI");assertEquals("provider",activity.page);activity.form.key.setText("SYNTHETIC_KEY");tap("保存 API 配置");assertEquals(1,app.store.providers().length());JSONObject p=app.store.providers().getJSONObject(0);assertTrue(p.getString("keyCipher").startsWith("SYNTHETIC_CIPHER_"));assertFalse(p.has("apiKey"));tap("返回聊天");assertEquals("chat",activity.page);assertTrue(activity.modelLabel.getText().toString().contains("DeepSeek"));assertNull(app.store.active());}
 @Test public void backupImportIntoFreshDatabasePreservesMessagesAndHasNoKeys()throws Exception{saveProvider();JSONObject r=app.store.reserve(activity.chatId,"合成备份问题");app.store.begin(r.getString("id"));ApiProtocol.Output o=new ApiProtocol.Output();o.text.append("合成备份部分内容");app.store.partial(r.getString("id"),o);JSONObject b=app.store.backup();app.store.close();app.deleteDatabase("ai-workspace.sqlite");Store fresh=new Store(app);assertTrue(fresh.restore(b)>0);assertNull(fresh.active());assertEquals("interrupted",fresh.request(r.getString("id")).getString("status"));assertEquals("合成备份部分内容",fresh.lastMessage(activity.chatId).getString("body"));assertEquals("",J.str(fresh.providers().getJSONObject(0),"keyCipher"));app.store=fresh;activity.store=fresh;}
 void tap(String label){View view=find(activity.root,label);assertNotNull(label,view);assertTrue(view.performClick());ShadowLooper.idleMainLooper();}
 View find(View view,String label){if(view instanceof TextView&&((TextView)view).getText().toString().equals(label))return view;if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int i=0;i<g.getChildCount();i++){View result=find(g.getChildAt(i),label);if(result!=null)return result;}}return null;}
 @Test public void attachmentsAndDraftsStayWithTheirOwnChat()throws Exception{String first=activity.chatId;activity.attachments.put(first,J.obj("name","合成附件.txt","body","合成附件"));activity.chatPage();assertNotNull(activity.attachment);activity.newChat();assertNull(activity.attachment);activity.openChat(first);assertEquals("合成附件.txt",activity.attachment.getString("name"));}
 @Test public void stoppedRequestCannotBeOverwrittenByLateReply()throws Exception{saveProvider();JSONObject r=app.store.reserve(activity.chatId,"合成停止请求");String id=r.getString("id");app.store.begin(id);ApiProtocol.Output before=new ApiProtocol.Output();before.text.append("合成已保存部分");app.store.partial(id,before);app.engine.cancel();ApiProtocol.Output late=new ApiProtocol.Output();late.text.append("合成迟到内容");app.store.finish(id,"done",late,"");assertEquals("stopped",app.store.request(id).getString("status"));assertEquals("合成已保存部分",app.store.lastMessage(activity.chatId).getString("body"));JSONObject followup=app.store.reserve(activity.chatId,"请接着合成部分继续");assertTrue(followup.getJSONObject("data").getJSONObject("payload").toString().contains("合成已保存部分"));}
 @Test public void actualCreateProjectButtonOpensNewProjectChat()throws Exception{activity.projectPage("");ArrayList<EditText> fields=new ArrayList<>();collectFields(activity.body,fields);fields.get(0).setText("合成按钮项目");fields.get(1).setText("合成项目指令");tap("保存项目");assertEquals("chat",activity.page);assertEquals("合成按钮项目",app.store.project(activity.projectId).getString("name"));assertEquals(activity.projectId,app.store.chat(activity.chatId).getString("projectId"));}
 void collectFields(View v,ArrayList<EditText> out){if(v instanceof EditText)out.add((EditText)v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)collectFields(g.getChildAt(i),out);}}
 @Test public void welcomeScreenshot()throws Exception{capture("welcome.png");saveProvider();JSONObject request=app.store.reserve(activity.chatId,"这是一条合成界面测试消息");app.store.begin(request.getString("id"));ApiProtocol.Output output=new ApiProtocol.Output();output.text.append("当然。你可以为每个项目保存说明和资料，再切换不同的 AI 来讨论。\n\n**先从一个想法开始。**\n\n```python\nprint(\"Hello, workspace\")\n```");app.store.finish(request.getString("id"),"done",output,"");activity.chatPage();capture("chat.png");activity.providerPage("",3);capture("provider.png");}
 void capture(String name)throws Exception{ShadowLooper.idleMainLooper();View view=activity.getWindow().getDecorView();view.measure(View.MeasureSpec.makeMeasureSpec(393,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(852,View.MeasureSpec.EXACTLY));view.layout(0,0,393,852);Bitmap image=Bitmap.createBitmap(393,852,Bitmap.Config.ARGB_8888);view.draw(new Canvas(image));File folder=new File(System.getProperty("workspace.screenshots","/tmp/ai-workspace-screenshots"));folder.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(folder,name))){image.compress(Bitmap.CompressFormat.PNG,100,out);}}
}
